--- a/src/Lab/LabResponse.php
+++ b/src/Lab/LabResponse.php
@@ -8,14 +8,27 @@ final class LabResponse

     public const UNKNOWN = 'unknown';

-    public function status(string $body): string
-    {
-        return self::UNKNOWN;
+    public function status(string $body): string
+    {
+        $data = json_decode($body);
+
+        if (!is_array($data)) {
+            return self::UNKNOWN;
+        }
+
+        return $data['status'] ?? self::UNKNOWN;
+    }
+
+    public function isReady(string $body): bool
+    {
+        return $this->status($body) === 'ready';
     }
 }
